def can_use(bundle: tuple[Regions, "SohWorld"], item: Items) -> Rule:
    rule : Rule = has_item(bundle, item)
    data = item_data_table

    if item in data:
        if data[item].adult_only:
            rule &= is_adult(bundle)

        if data[item].child_only:
            rule &= is_child(bundle)

        if data[item].item_type == ItemType.magic:
            rule &= has_item(bundle, Items.RG_MAGIC_SINGLE)

        if data[item].item_type == ItemType.song:
            rule &= can_play_song(bundle, item)

    if item in (Items.RG_FIRE_ARROWS, Items.RG_ICE_ARROWS, Items.RG_LIGHT_ARROWS):
        rule &= can_use(bundle, Items.RG_FAIRY_BOW)

    if item in (Items.RG_PROGRESSIVE_BOMBCHU_BAG, Items.RG_BOMBCHU_5, Items.RG_BOMBCHU_10, Items.RG_BOMBCHU_20):
        from .functions_gen import bombchu_refill  # generated, and it imports this module
        rule &= bombchu_refill(bundle)

    if item == Items.RG_FISHING_POLE:
        rule &= has_item(bundle, Items.RG_CHILD_WALLET)

    if item == Items.RG_EPONA:
        rule &= is_adult(bundle) & can_use(bundle, Items.RG_EPONAS_SONG)
    
    return rule



BOTTLE_ITEMS = frozenset({
    Items.RG_BOTTLE_WITH_BLUE_FIRE, Items.RG_BOTTLE_WITH_BLUE_POTION, Items.RG_BOTTLE_WITH_BUGS,
    Items.RG_BOTTLE_WITH_FAIRY, Items.RG_BOTTLE_WITH_FISH, Items.RG_BOTTLE_WITH_GREEN_POTION,
    Items.RG_BOTTLE_WITH_MILK, Items.RG_BOTTLE_WITH_POE, Items.RG_BOTTLE_WITH_RED_POTION, Items.RG_EMPTY_BOTTLE,
})


def has_item(bundle: tuple[Regions, "SohWorld"], item: Items | Events | StrEnum, count: int = 1) -> Rule:
    if item == Items.RG_STICKS:
        return has_item(bundle, Events.LOGIC_STICK_ACCESS) & has_item(bundle, Items.RG_DEKU_STICK_BAG)

    if item in (Items.RG_PROGRESSIVE_BOMBCHU_BAG, Items.RG_BOMBCHU_5, Items.RG_BOMBCHU_10, Items.RG_BOMBCHU_20):
        return bombchus_enabled(bundle)

    if item == Items.RG_NUTS:
        return has_item(bundle, Events.LOGIC_NUT_ACCESS) & has_item(bundle, Items.RG_DEKU_NUT_BAG)

    if item == Items.RG_MAGIC_BEAN:
        return HasAny(Items.RG_MAGIC_BEAN_PACK, HostEvents.CAN_BUY_BEANS)

    if item == Items.RG_DEKU_SHIELD:
        return Has(Items.RG_BUY_DEKU_SHIELD)

    if item == Items.RG_HYLIAN_SHIELD:
        return Has(Items.RG_BUY_HYLIAN_SHIELD)

    if item == Items.RG_GORON_TUNIC:
        return HasAny(Items.RG_BUY_GORON_TUNIC, Items.RG_GORON_TUNIC)

    if item == Items.RG_ZORA_TUNIC:
        return HasAny(Items.RG_BUY_ZORA_TUNIC, Items.RG_ZORA_TUNIC)

    if item in MASK_BORROW_EVENTS:
        return (MASK_QUEST_SHUFFLED & Has(item)) | (MASK_QUEST_NOT_SHUFFLED & Has(MASK_BORROW_EVENTS[item]))

    if item in (Items.RG_SCARECROW, Items.RG_DISTANT_SCARECROW):
        from .functions_gen import scarecrows_song
        return scarecrows_song(bundle) & can_use(
            bundle, Items.RG_HOOKSHOT if item == Items.RG_SCARECROW else Items.RG_LONGSHOT)

    if item == Items.RG_FISHING_POLE:
        return OptionFilter(ShuffleFishingPole, False) | Has(Items.RG_FISHING_POLE)

    if item == Events.LOGIC_BUY_BOMBCHUS:
        return HasAny(Items.RG_BUY_BOMBCHUS_10, Items.RG_BUY_BOMBCHUS_20)

    if item == Items.RG_EPONA:
        return Has(Events.LOGIC_FREED_EPONA)

    if item in ABILITY_SHUFFLES:
        return OptionFilter(ABILITY_SHUFFLES[item], False) | Has(item)

    if item in {Items.RG_POCKET_EGG, Items.RG_COJIRO, Items.RG_ODD_MUSHROOM, Items.RG_ODD_POTION, Items.RG_POACHERS_SAW,
                Items.RG_BROKEN_SWORD, Items.RG_PRESCRIPTION, Items.RG_EYEBALL_FROG, Items.RG_EYEDROPS}:
        return OptionFilter(RSK_SHUFFLE_ADULT_TRADE, False) | Has(item)

    if item in BOTTLE_ITEMS:
        from .functions_gen import has_bottle
        bottle = has_bottle(bundle)
        if item == Items.RG_BOTTLE_WITH_BLUE_FIRE:
            return bottle & (Has(Events.LOGIC_BLUE_FIRE_ACCESS) | Has(Items.RG_BUY_BLUE_FIRE))
        if item == Items.RG_BOTTLE_WITH_BLUE_POTION:
            return bottle & Has(Items.RG_BUY_BLUE_POTION)
        if item == Items.RG_BOTTLE_WITH_BUGS:
            return bottle & (Has(Events.LOGIC_BUG_ACCESS) | Has(Items.RG_BUY_BOTTLE_BUG))
        if item == Items.RG_BOTTLE_WITH_FAIRY:
            return bottle & (Has(Events.LOGIC_FAIRY_ACCESS) | Has(Items.RG_BUY_FAIRYS_SPIRIT))
        if item == Items.RG_BOTTLE_WITH_FISH:
            return bottle & (Has(Events.LOGIC_FISH_ACCESS) | Has(Items.RG_BUY_FISH))
        if item == Items.RG_BOTTLE_WITH_GREEN_POTION:
            return bottle & Has(Items.RG_BUY_GREEN_POTION)
        return bottle  # milk, poe, red potion, empty

    for prog,non_progs in progressive_items.items():
        if item in non_progs:
            return Has(prog, non_progs.index(item) + 1)

    return Has(item, count)



@dataclasses.dataclass
class CanAffordSlot(Rule, game="Ship of Harkinian"):
    location: Locations

    def _instantiate(self, world: "SohWorld") -> Rule.Resolved: # type: ignore
        return self.Resolved(location = self.location, player = world.player,
                             caching_enabled=getattr(world, "rule_caching_enabled", False))

    class Resolved(Rule.Resolved):
        location: Locations
        #player: int
        
        def _evaluate(self, state: CollectionState) -> bool:
            world = state.multiworld.worlds[self.player]
            wallet = get_wallet_for_shop_slot(self.location, world)[0] #type: ignore
            prog_wallet_count = progressive_items[Items.RG_PROGRESSIVE_WALLET].index(wallet) + 1
            return state.has(Items.RG_PROGRESSIVE_WALLET, self.player, prog_wallet_count)

        def item_dependencies(self) -> dict[str, set[int]]:
            return {str(Items.RG_PROGRESSIVE_WALLET): {id(self)}}
        
        @override
        def explain_json(self, state: CollectionState | None = None) -> list[JSONMessagePart]:
            data = get_wallet_for_shop_slot(self.location, state.multiworld.worlds[self.player])
            verb = "Missing " if state and not self(state) else "Has "
            messages: list[JSONMessagePart] = [{"type": "text", "text": verb}]
            if state:
                color = "green" if self(state) else "salmon"
                messages.append({"type": "color", "color": color, "text": data[0]})
                messages.append({"type": "text", "text": f" to buy item for "})
                messages.append({"type": "color", "color": "cyan", "text": str(data[1])})
                messages.append({"type": "text", "text": f" rupees"})
            else:
                messages.append({"type": "item_name", "flags": 0b001, "text": data[0], "player": self.player})
            return messages

        @override
        def explain_str(self, state: CollectionState | None = None) -> str:
            data = get_wallet_for_shop_slot(self.location, state.multiworld.worlds[self.player])
            if state is None:
                return str(self)
            prefix = "Has" if self(state) else "Missing"
            return f"{prefix} {data[0]} to buy item for {str(data[1])} rupees"

        @override
        def __str__(self) -> str:
            return f"Has wallet large enough to buy the item at {str(self.location)}"


def get_wallet_for_shop_slot(location: Locations, world: "SohWorld") -> tuple[str, int]:
    price = world.shop_prices.get(location, 500)
    for wallet, amount in wallet_capacities.items():
        if amount >= price:
            return str(wallet), price

def can_afford_slot(slot: Locations) -> Rule:
    return CanAffordSlot(slot)


#Exists just to make the bottle rule somewhat more understandable in explains
@dataclasses.dataclass()
class HasBottleCount(WrapperRule, game="Ship of Harkinian"):
    count: int

    def _instantiate(self, world: World) -> Rule.Resolved:
        return self.Resolved(
            self.child.resolve(world),
            player=world.player,
            caching_enabled=getattr(world, "rule_caching_enabled", False),
            count = self.count
        )

    class Resolved(WrapperRule.Resolved):
        count: int
        
        @override
        def explain_json(self, state: CollectionState | None = None) -> list[JSONMessagePart]:
            verb = "Does not have " if state and not self(state) else "Has "
            messages: list[JSONMessagePart] = [{"type": "text", "text": verb}]
            bottles = "bottles" if self.count > 1 else "bottle"
            if state:
                messages.append({"type": "color", "color": "cyan", "text": f"{self.count} "})
                messages.append({"type": "text", "text": f"emptiable {bottles}"})
            else:
                messages.append({"type": "text", "text": f"at least {self.count} emptiable {bottles}"})
            return messages

        @override
        def explain_str(self, state: CollectionState | None = None) -> str:
            if state is None:
                return str(self)
            return f"{"Has" if self(state) else "Does not have"} {self.count} emptiable bottle{"s" if self.count > 1 else ""}"

        @override
        def __str__(self) -> str:
            return f"Has {self.count} bottle{"s" if self.count>1 else ""}"


def has_bottle_count(bundle: tuple[Regions, "SohWorld"], target_count: int) -> Rule:
    return HasBottleCount( \
        (HasAll(Events.LOGIC_DELIVER_RUTOS_LETTER, Events.LOGIC_CAN_EMPTY_BIG_POES) & HasFromList(*no_rules_bottles, Items.RG_BOTTLE_WITH_BIG_POE, Items.RG_RUTOS_LETTER, count=target_count)) \
            | (Has(Events.LOGIC_DELIVER_RUTOS_LETTER) & HasFromList(*no_rules_bottles, Items.RG_RUTOS_LETTER, count=target_count)) \
            | (Has(Events.LOGIC_CAN_EMPTY_BIG_POES) & HasFromList(*no_rules_bottles, Items.RG_BOTTLE_WITH_BIG_POE, count=target_count)) \
            | HasFromList(*no_rules_bottles, count=target_count) \
        , count = target_count)


def bombchus_enabled(bundle: tuple[Regions, "SohWorld"]) -> Rule:
    return Has(Items.RG_PROGRESSIVE_BOMBCHU_BAG) | Has(Items.RG_PROGRESSIVE_BOMB_BAG, options=[OptionFilter(BombchuBag, False)])


