class SohHeartState(LogicMixin):
    # tracking how many hearts the player has instead of checking the collection state every time
    soh_piece_of_heart_count: Counter[int]
    soh_heart_count: Counter[int]

    def init_mixin(self, parent: MultiWorld):
        soh_players = list(parent.get_game_players(
            "Ship of Harkinian") + parent.get_game_groups("Ship of Harkinian"))
        self.soh_piece_of_heart_count = Counter()
        self.soh_heart_count = Counter({player: cast("SohWorld", parent.worlds[player]).options.starting_hearts.value for player in soh_players})

    def copy_mixin(self, ret: CollectionState) -> CollectionState:
        ret.soh_piece_of_heart_count = Counter(self.soh_piece_of_heart_count)  # type: ignore # noqa
        ret.soh_heart_count = Counter(self.soh_heart_count)  # type: ignore # noqa
        return ret


def scene_is_mq(region, world: "SohWorld") -> bool:
    return REGION_SCENE.get(region) in world.mq_scenes


def region_is_active(region, world: "SohWorld") -> bool:
    """False for a region belonging to the quest variant this seed did not roll."""
    region_quest = REGION_QUEST.get(region, "")
    return not region_quest or (region_quest == "mq") == scene_is_mq(region, world)


def add_locations(parent_region, world: "SohWorld", locations) -> None:
    """Collect locations to be processed in materialize_locations"""
    if not region_is_active(parent_region, world):
        return
    for entry in locations:
        world._soh_pending_locations.setdefault(entry[0], []).append((parent_region, entry[1]))


TIME_PASSING_REGIONS = [Regions.RR_HYRULE_FIELD, Regions.RR_ZR_FRONT, Regions.RR_DEATH_MOUNTAIN_TRAIL,
                        Regions.RR_DESERT_COLOSSUS, Regions.RR_LAKE_HYLIA, Regions.RR_GERUDO_VALLEY]


def add_host_events(world: "SohWorld") -> None:
    """Events the world supplies because RLS has no equivalent. Call after `set_region_rules`."""
    add_events(Regions.RR_TOT_BEYOND_DOOR_OF_TIME, world, [
        ("Time Travel", HostEvents.TIME_TRAVEL, lambda bundle: True_()),
    ])
    root_exit = world.get_entrance(f"{Regions.RR_ROOT} -> {Regions.RR_ROOT_EXITS}")
    world.set_rule(root_exit, starting_age((Regions.RR_ROOT, world)) | Has(HostEvents.TIME_TRAVEL))

    for region in TIME_PASSING_REGIONS:
        add_events(region, world, [
            (f"{region} Child Passes Time", HostEvents.CHILD_CAN_PASS_TIME, lambda bundle: is_child(bundle)),
            (f"{region} Adult Passes Time", HostEvents.ADULT_CAN_PASS_TIME, lambda bundle: is_adult(bundle)),
        ])


def prune_unreachable_events(world: "SohWorld") -> list[str]:
    """Remove RLS event locations that no state can reach. Call once entrances are final."""
    state = world.multiworld.get_all_state(False)
    dead = [loc for loc in world.get_locations()
            if loc.name in _EVENT_LOCATION_NAMES and not loc.can_reach(state)]
    for loc in dead:
        loc.parent_region.locations.remove(loc)
    return [loc.name for loc in dead]


_EVENT_LOCATION_NAMES = frozenset(str(name) for name in EventLocations)


@dataclasses.dataclass
class AnyAge(WrapperRule, game="Ship of Harkinian"):
    parent_region: Regions

    def _instantiate(self, world: "SohWorld") -> Rule.Resolved: # type: ignore
        return self.Resolved(self.child.resolve(world), parent_region=self.parent_region,
                             player=world.player,
                             caching_enabled=getattr(world, "rule_caching_enabled", False))

    class Resolved(WrapperRule.Resolved):
        parent_region: Regions
        force_recalculate = True

        @override
        def _evaluate(self, state: CollectionState) -> bool:
            ages = state._soh_region_ages(self.parent_region, self.player) # type: ignore
            child, adult = ages
            result = False
            if child or adult:
                prev = state._soh_widen[self.player] # type: ignore
                state._soh_widen[self.player] = ages # type: ignore
                try:
                    result = self.child(state)
                finally:
                    state._soh_widen[self.player] = prev # type: ignore
            if not result and not (child and adult):
                state._soh_widen_pending[self.player].setdefault(self.parent_region, ages) # type: ignore
            return result

        @override
        def region_dependencies(self) -> dict[str, set[int]]:
            deps = super().region_dependencies()
            deps.setdefault(self.parent_region.value, set()).add(id(self))
            return deps

        @override
        def explain_str(self, state: CollectionState | None = None) -> str:
            return f"As any age in {self.parent_region}[{self.child.explain_str(state)}]"

        @override
        def __str__(self) -> str:
            return f"As any age in {self.parent_region}[{self.child}]"


@dataclasses.dataclass
class BothAges(Rule, game="Ship of Harkinian"):
    parent_region: Regions

    def _instantiate(self, world: "SohWorld") -> Rule.Resolved:  # type: ignore
        return self.Resolved(parent_region=self.parent_region, player=world.player,
                             caching_enabled=getattr(world, "rule_caching_enabled", False))

    class Resolved(Rule.Resolved):
        parent_region: Regions
        force_recalculate = True

        def _evaluate(self, state: CollectionState) -> bool:
            ages = state._soh_region_ages(self.parent_region, self.player)  # type: ignore
            if all(ages):
                return True
            state._soh_widen_pending[self.player].setdefault(self.parent_region, ages)  # type: ignore
            return False

        def item_dependencies(self) -> dict[str, set[int]]:
            return {}

        def region_dependencies(self) -> dict[str, set[int]]:
            return {self.parent_region.value: {id(self)}}

        def __str__(self) -> str:
            return f"As both ages in {self.parent_region}"


def is_mq(bundle) -> Rule:
    return True_() if scene_is_mq(*bundle) else False_()


def is_vanilla(bundle) -> Rule:
    return False_() if scene_is_mq(*bundle) else True_()


def trial_skipped(bundle, trial: TrialKey) -> Rule:
    _, world = bundle
    return False_() if trial in world.ganons_trials else True_()


def can_plant_bean(bundle, region: Regions, bean: Items) -> Rule:
    return has_item(bundle, bean) & has_item(bundle, Items.RG_MAGIC_BEAN) & BothAges(parent_region=region)


def spirit_certain_access(bundle, region: Regions) -> Rule:
    # TODO Add Spirit Logic
    return CanReachRegion(region.value)


def spirit_shared(bundle, region: Regions, condition, any_age: bool = False,
                  second_region: Regions = None, second_condition=None,
                  third_region: Regions = None, third_condition=None) -> Rule:
    # TODO Add Spirit Logic 
    pairs = [(region, condition), (second_region, second_condition), (third_region, third_condition)]
    rule = False_()
    for parent, cond in pairs:
        if parent is None or parent == Regions.RR_NONE or cond is None:
            continue
        branch = cond((parent, bundle[1]))
        reach = CanReachRegion(parent.value)
        rule = rule | (AnyAge(reach & branch, parent_region=parent) if any_age else reach & branch)
    return rule
